import{c as t,W as a,j as i,n as o}from"./chunks/framework.DBclLOWj.js";const u=JSON.parse('{"title":"Make Preview Teardown Final","description":"","frontmatter":{"id":"proposal.0002","title":"Make Preview Teardown Final","authors":["markmals","Claude"],"status":"draft","pull-request":"https://github.com/markmals/workbench/pull/5","issues":["https://github.com/markmals/workbench/issues/3"],"supersedes":[]},"headers":[],"relativePath":"proposals/0002-final-preview-teardown.md","filePath":"proposals/0002-final-preview-teardown.md"}'),s={name:"proposals/0002-final-preview-teardown.md"};function n(r,e,d,l,h,c){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="make-preview-teardown-final" tabindex="-1">Make Preview Teardown Final <a class="header-anchor" href="#make-preview-teardown-final" aria-label="Permalink to “Make Preview Teardown Final”">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to “Summary”">​</a></h2><p>A preview deployment can survive its pull request. The deploy job now confirms the pull request is still open immediately before publishing, so a late-arriving run cannot resurrect a preview that was already torn down.</p><h2 id="motivation" tabindex="-1">Motivation <a class="header-anchor" href="#motivation" aria-label="Permalink to “Motivation”">​</a></h2><p>Closing a pull request is supposed to remove its preview. On pull request 1 it did not, and the preview stayed live until it was removed by hand.</p><p>Both fixes suggested when the defect was filed would have failed, which is the reason this is worth a proposal rather than a patch. The observed timings show why:</p><table tabindex="0"><thead><tr><th>Run</th><th>Created</th><th>Finished</th><th>Build steps</th><th>Effect</th></tr></thead><tbody><tr><td><code>33020579883</code></td><td>22:43:31</td><td>22:43:47</td><td>skipped</td><td>removed the preview</td></tr><tr><td><code>33020601519</code></td><td>22:43:53</td><td>22:44:28</td><td>ran</td><td>re-deployed it</td></tr></tbody></table><p>The deploy run was <strong>created six seconds after the removal run had already finished</strong>. The two never coexisted. Concurrency controls only order runs that overlap: <code>cancel-in-progress</code> cancels what is currently running, and a queued run is cancelled only by a newer queued run in the same group. Neither applies to a run that does not exist yet.</p><p>So the guess in the issue — that the concurrency group failed to serialize them — is wrong. Nothing about concurrency configuration can fix this, because the race is between a webhook delivery and a completed workflow.</p><p>The underlying error is a category one: the deploy path trusts an event payload describing the world at the moment the event fired, and acts on it later without rechecking. <code>mise run status</code> already refuses to guess about state it cannot confirm; this workflow does not.</p><h2 id="proposed-solution" tabindex="-1">Proposed solution <a class="header-anchor" href="#proposed-solution" aria-label="Permalink to “Proposed solution”">​</a></h2><p>Split the workflow into a deploy job and a remove job, then have the deploy job ask GitHub whether the pull request is still open at the moment it is about to publish, and stop if it is not.</p><p>Removal becomes final: once a pull request closes, no later run can publish for it, regardless of when the run was created or how long it queued.</p><h2 id="detailed-design" tabindex="-1">Detailed design <a class="header-anchor" href="#detailed-design" aria-label="Permalink to “Detailed design”">​</a></h2><p><code>.github/workflows/preview.yml</code> becomes two jobs with mutually exclusive conditions, replacing the current single job whose steps carry per-step <code>if</code> guards.</p><p><strong><code>remove</code></strong> — runs when <code>github.event.action == &#39;closed&#39;</code>. Checks out, then invokes <code>rossjrw/pr-preview-action</code> to remove. No build, so it stays fast.</p><p><strong><code>deploy</code></strong> — runs when <code>github.event.action != &#39;closed&#39;</code>. Before publishing, and after the build, it queries the live state of the pull request:</p><div class="language-sh"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-dark github-light" style="--shiki-dark:#e1e4e8;--shiki-light:#24292e;--shiki-dark-bg:#24292e;--shiki-light-bg:#fff;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-dark:#B392F0;--shiki-light:#6F42C1;">gh</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> pr</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> view</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> &quot;</span><span style="--shiki-dark:#E1E4E8;--shiki-light:#24292E;">$PR_NUMBER</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;">&quot;</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --json</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> state</span><span style="--shiki-dark:#79B8FF;--shiki-light:#005CC5;"> --jq</span><span style="--shiki-dark:#9ECBFF;--shiki-light:#032F62;"> .state</span></span></code></pre></div><p>The publish step runs only when that returns <code>OPEN</code>. The query happens <strong>after</strong> the build rather than before it, so the window between the check and the publish is as small as possible — checking first and building for a minute would reopen the same race in miniature.</p><p>When the state is not <code>OPEN</code>, the job logs that it is skipping publication for a closed pull request and succeeds. A skipped publication is correct behavior, not a failure, and failing would put a red mark on a merged pull request for something nobody needs to act on.</p><p>The query needs <code>GITHUB_TOKEN</code> with <code>pull-requests: read</code>, which the workflow already grants.</p><p>Concurrency is unchanged. <code>cancel-in-progress</code> remains useful for superseded deploys; it is simply not what was broken.</p><h2 id="compatibility" tabindex="-1">Compatibility <a class="header-anchor" href="#compatibility" aria-label="Permalink to “Compatibility”">​</a></h2><p>No behavior change for any pull request that is still open. The only altered outcome is the one that was wrong.</p><h2 id="implications-on-adoption" tabindex="-1">Implications on adoption <a class="header-anchor" href="#implications-on-adoption" aria-label="Permalink to “Implications on adoption”">​</a></h2><p>None. Adopting projects that wired a different preview mechanism from the recipe menu should apply the same guard if their mechanism publishes on <code>synchronize</code>, which the comments in the workflow will note.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><ul><li>Split <code>preview.yml</code> into <code>deploy</code> and <code>remove</code> jobs.</li><li>Add the open-state guard to the deploy path.</li><li>Note the hazard in the recipe menu so adapted recipes inherit the fix.</li></ul><h3 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to “Out of scope”">​</a></h3><ul><li><strong>Sweeping already-stale previews.</strong> A scheduled job reconciling <code>gh-pages</code> against open pull requests would catch previews orphaned by other means. There are none — the one that existed was removed by hand — so this would be built for a problem that is not currently observed.</li><li><strong>Changing the concurrency configuration.</strong> It is not the cause. Changing it to look responsive would leave the actual defect in place.</li></ul><h2 id="preview" tabindex="-1">Preview <a class="header-anchor" href="#preview" aria-label="Permalink to “Preview”">​</a></h2><p>None. This change has no user-exercisable surface: it alters when a workflow publishes, and the observable result is the <em>absence</em> of a stale deployment.</p><p>The honest verification is behavioral rather than a preview — open a pull request, let it deploy, merge it, and confirm the preview is gone and stays gone. That is recorded in the readiness report.</p><h2 id="policies-and-decisions-checked" tabindex="-1">Policies and decisions checked <a class="header-anchor" href="#policies-and-decisions-checked" aria-label="Permalink to “Policies and decisions checked”">​</a></h2><p><code>policies/</code> and <code>decisions/</code> are both empty; both directories were read. <code>VISION.md</code> was read and this change is consistent with it.</p><p>One principle in <code>VISION.md</code> bears directly on the fix: <em>previews expose behavior, not descriptions of behavior.</em> A preview that outlives its pull request inverts that — it shows behavior from a revision nobody is reviewing.</p><p>This is a candidate for the first real decision entry: <strong>act on live state, not on a stale event payload.</strong> Whether one defect justifies a record is a judgement to make at completion, not now.</p><h2 id="future-directions" tabindex="-1">Future directions <a class="header-anchor" href="#future-directions" aria-label="Permalink to “Future directions”">​</a></h2><ul><li>A scheduled reconciliation between <code>gh-pages</code> and open pull requests, if previews are ever orphaned by a route this guard does not cover.</li><li>Applying the same live-state discipline to any other workflow that acts on an event payload after a delay. There are currently none.</li></ul><h2 id="alternatives-considered" tabindex="-1">Alternatives considered <a class="header-anchor" href="#alternatives-considered" aria-label="Permalink to “Alternatives considered”">​</a></h2><p><strong>Gate the build and deploy steps at the job level instead of per-step.</strong> Suggested in the issue. Rejected because it changes nothing about the outcome — the deploy run&#39;s steps were meant to run; it was a genuine deploy event. Job-level conditions are still worth adopting for readability, and this proposal does adopt them, but as tidying rather than as the fix.</p><p><strong>Drop <code>cancel-in-progress</code> for the close path.</strong> Also suggested in the issue. Rejected on the evidence: the two runs never overlapped, so nothing was there to cancel. This would have looked like a fix while leaving the defect intact — the worst outcome available, because the issue would have been closed.</p><p><strong>Have the remove job re-run on a delay to catch late deploys.</strong> Rejected as a race against a race. It narrows the window without closing it, and it makes teardown timing nondeterministic.</p><p><strong>Check the pull request state before building rather than after.</strong> Rejected because it leaves a minute-wide window between the check and the publish, which is the same defect with a smaller constant.</p><h2 id="open-questions" tabindex="-1">Open questions <a class="header-anchor" href="#open-questions" aria-label="Permalink to “Open questions”">​</a></h2><p>None.</p>',46)])])}const w=t(s,[["render",n]]);export{u as __pageData,w as default};
